PURE_ORIGINALS={'chaos/module_values.py:request': "def request(evaluator,program,bindings=None):\n    from .program_values import owned\n    from .class_creation import validate_value\n    owned(program,evaluator)\n    if type(bindings) is not dict or len(bindings)>256:\n        raise LanguageError('module_from bindings 需要至多256项 Record',code='module_error')\n    associations=dict(bindings)\n    for name,value in associations.items():\n        evaluator.tick()\n        if type(name) is not str or len(name)>240 or re.fullmatch(r'[^\\W\\d]\\w*',name,re.UNICODE) is None or name in Parser.reserved:\n            raise LanguageError('module_from bindings 名称无效',code='module_error')\n        validate_value(evaluator,value)\n    return Request(program,tuple(associations.items()))\n", 'chaos/module_values.py:Scope.__init__': "def __init__(self,evaluator,value):\n    from .program_values import owned\n    from .class_creation import validate_value\n    from .modules import ProgramBundle\n    owned(value.program,evaluator)\n    for _,item in value.bindings:validate_value(evaluator,item)\n    definition=value.program.definition\n    self.evaluator=evaluator\n    self.bundle=ProgramBundle(definition['files'][definition['entry']],definition['files'],definition['entry'],language_versions=definition['languageVersions'],checkpoint=evaluator.tick)\n    self.definition=definition\n    self.bindings=value.bindings\n    self.cache={}\n    self.loading=set()\n    prefix='module/'+value.program.definition_hash+'/'\n    self.virtual={name:prefix+hashlib.sha256(name.encode()).hexdigest()+'.chaos' for name in self.bundle.trees}\n    context={'entry':self.bundle.entry,'virtualFiles':{name:self.virtual[name] for name in self.bundle.files},'languageVersions':dict(self.bundle.language_versions)}\n    context_json=json.dumps(context,sort_keys=True,ensure_ascii=False,separators=(',',':'))\n    from .modules import STDLIB\n    from .program import parse_program\n    from .generated_sources import Source,register_batch\n    sources={}\n    for name,file in self.virtual.items():\n        evaluator.tick();text=STDLIB[name] if name in STDLIB else self.bundle.files[name]\n        version=self.bundle.language_versions.get(name,2)\n        ir=parse_program(text,file,language_version=version)\n        sources[name]=Source(file,text,version,hashlib.sha256(text.encode()).hexdigest(),ir['semanticHash'],context_json if name in self.bundle.files else None)\n    # Validate the whole source batch before publishing any registry entry.\n    register_batch(evaluator,tuple(sources.values()))\n    self.sources=sources\n    for name,tree in self.bundle.expanded_trees.items():\n        pending=[tree]\n        while pending:\n            evaluator.tick();item=pending.pop()\n            if isinstance(item,Node):\n                logical=item.span.get('file')\n                if logical in self.virtual:\n                    item.span=dict(item.span,file=self.virtual[logical]);item._generated_source=sources[logical]\n                item._module_scope=self;item._module_file=name\n                pending.extend(item[1:])\n            elif type(item) in (tuple,list):pending.extend(item)\n"}

TARGETS=('scope.load','scope.imported','construct','legacy.load','syntax.import','syntax.export','export.run')
class RetainedOriginal:
    def __init__(self,iterator,name,reached,retained,code):
        self.iterator=iterator;self.name=name;self.reached=reached;self.started=False
        retained.append((self,iterator,code))
    def __iter__(self):return self
    def __next__(self):return self.send(None)
    def send(self,value):
        if not self.started:
            self.started=True
            if self.name in self.reached:self.reached[self.name]+=1
        return self.iterator.send(value)
    def throw(self,*args):return self.iterator.throw(*args)
    def close(self):return self.iterator.close()
def original(path,name,module):
    namespace={'__name__':module.__name__,'__package__':'chaos'}
    exec(compile(ORIGINALS[path+':'+name],__file__+':'+name,'exec'),namespace)
    compiled=namespace[name.rsplit('.',1)[-1]]
    result=FunctionType(compiled.__code__,vars(module),compiled.__name__,compiled.__defaults__,compiled.__closure__)
    result.__kwdefaults__=compiled.__kwdefaults__
    return result
@contextmanager
def reference(retained=None):
    from chaos import language,module_values
    from chaos.execution_modules import ModuleSyntaxFrame
    reached={name:0 for name in TARGETS};held=[]if retained is None else retained
    rows=[(module_values.Scope,'load','scope.load','chaos/module_values.py','Scope.load',module_values),
          (module_values.Scope,'imported','scope.imported','chaos/module_values.py','Scope.imported',module_values),
          (module_values,'construct','construct','chaos/module_values.py','construct',module_values),
          (language.Evaluator,'_s_execute',None,'chaos/language.py','Evaluator._s_execute',language),
          (language.Evaluator,'_s_export','export.run','chaos/language.py','Evaluator._s_export',language)]
    with ExitStack()as stack:
        stack.enter_context(patch.object(ModuleSyntaxFrame,'KINDS',set()))
        for target,attribute,label,path,name,module in rows:
            function=original(path,name,module)
            def old(*args,_function=function,_label=label,**kwargs):
                label=_label
                if label is None:
                    kind=args[1][0];label='syntax.'+kind if kind in ('import','export')else None
                return RetainedOriginal(_function(*args,**kwargs),label,reached,held,_function.__code__)
            stack.enter_context(patch.object(target,attribute,old))
        function=original('chaos/language.py','Evaluator.load_module',language)
        def eager(e,name):
            reached['legacy.load']+=1
            return function(e,name)
        stack.enter_context(patch.object(language.Evaluator,'load_module',eager))
        yield reached
